const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (line) => {
  const [n, sx, sy, dx, dy, t] = line.split(' ').map(Number);
  let x = sx;
  let y = sy;
  let currentDx = dx;
  let currentDy = dy;
  for (let i = 0; i < t; i++) {
    const k = x + y;
    currentDx += k;
    currentDy += k;
    x = ((x + currentDx - 1) % n + n) % n + 1;
    y = ((y + currentDy - 1) % n + n) % n + 1;
  }
  console.log(x, y);
  rl.close();
});
