    let y = sy;

    for (let i = 0n; i < t; i++) {
        const k = (x + y) % n;
        dx = (dx + k) % n;
        dy = (dy + k) % n;

        x = ((x + dx - 1n) % n + n) % n + 1n;
        y = ((y + dy - 1n) % n + n) % n + 1n;
    }

    console.log(Number(x) + ' ' + Number(y));
    rl.close();
});
